class TrieNode:
    def __init__(self):
        self.children = {}   # letter -> TrieNode
        self.count = 0       # how many inserted words pass through this node

def solution(ops):
    root = TrieNode()
    answers = []
    for name, word in ops:
        if name == "insert":
            node = root
            node.count += 1                  # every word starts with ""
            for ch in word:
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
                node.count += 1
        else:
            node = root
            for ch in word:
                node = node.children.get(ch)
                if node is None:             # fell off the trie: no match
                    break
            answers.append(node.count if node is not None else 0)
    return answers

