def solution(ops):
    # Keep every word and test each one on every query: O(words) per count.
    words = []
    answers = []
    for name, word in ops:
        if name == "insert":
            words.append(word)
        else:
            answers.append(sum(1 for w in words if w.startswith(word)))
    return answers
